// data/voice/amy.js — amy's baked clips (loaded after data/voice-clips.js). Merge from the Voice Baker; do not hand-edit.
VOICE_CLIPS.clips.amy={"greet":[{"text":"Grace! Rose! Did you stretch?","mp3":"","model":"eleven_v4"},{"text":"Tom, I ran eight miles before you woke up.","mp3":"","model":"eleven_v4"},{"text":"Race you to the fountain. No? Then I win.","mp3":"","model":"eleven_v4"}],"basic":[{"text":"Coming through! Hydrate later!","mp3":"","model":"eleven_v4"},{"text":"Heads up! Mom has a record to set!","mp3":"","model":"eleven_v4"}],"hurt":[{"text":"Hey! That's a time penalty!","mp3":"","model":"eleven_v4"},{"text":"Ow! Second graders hit harder than that!","mp3":"","model":"eleven_v4"}],"win":[{"text":"That's how this family does it!","mp3":"","model":"eleven_v4"},{"text":"Faster than Tom. As usual.","mp3":"","model":"eleven_v4"}],"praise":[{"text":"Neatest handwriting in the building. And I check.","mp3":"","model":"eleven_v4"},{"text":"Your margins are immaculate. Gold star.","mp3":"","model":"eleven_v4"},{"text":"Present. I have never missed a connection in my life.","mp3":"","model":"eleven_v4"},{"text":"Here! Gregori, party of four. We are always first in line.","mp3":"","model":"eleven_v4"}],"join":[{"text":"Need a fourth? I'm fast, I'm loud, and I brought a whistle!","mp3":"","model":"eleven_v4"}],"burpee":[{"text":"Five burpees! Four! Three! You're next!","mp3":"","model":"eleven_v4"}],"redpen":[{"text":"F. F. And see me after class.","mp3":"","model":"eleven_v4"}],"finish":[{"text":"I see the finish line. It's you.","mp3":"","model":"eleven_v4"}],"quiz":[{"text":"Pop quiz! Eyes on your own puddle!","mp3":"","model":"eleven_v4"}],"hills":[{"text":"Hill repeats! Up the slime, down the slime!","mp3":"","model":"eleven_v4"}],"marathon":[{"text":"Twenty-six point two! Straight through the slime!","mp3":"","model":"eleven_v4"}],"pep":[{"text":"Eyes up, team! Stretching is over!","mp3":"","model":"eleven_v4"},{"text":"Thirty seconds! Give me everything you've got!","mp3":"","model":"eleven_v4"}],"pb":[{"text":"New personal best! Write it down, Tom!","mp3":"","model":"eleven_v4"}],"kettlebell_swing":[{"text":"Kettlebell swing! Hips, not back!","mp3":"","model":"eleven_v4"}],"hot_lunch_tray":[{"text":"Hot lunch! Soup first, then recess.","mp3":"","model":"eleven_v4"}],"goldstar_recess":[{"text":"Gold-star recess. Rest counts as good work.","mp3":"","model":"eleven_v4"}],"inside_voices":[{"text":"Inside voices, please. I will wait.","mp3":"","model":"eleven_v4"}],"oat_milk_please":[{"text":"No dairy, thank you. Oat milk, please!","mp3":"","model":"eleven_v4"}],"false_start":[{"text":"False start. Back behind the line.","mp3":"","model":"eleven_v4"}],"negative_split":[{"text":"Negative split! The second half is FASTER!","mp3":"","model":"eleven_v4"}],"detention_ult":[{"text":"Nobody leaves this room until that chalkboard is spotless!","mp3":"","model":"eleven_v4"}],"marathon_ult":[{"text":"Right on Hereford, left on Boylston! Sprint to the tape!","mp3":"","model":"eleven_v4"}],"low":[{"text":"Walking it off. Walking it off.","mp3":"","model":"eleven_v4"}],"ko":[{"text":"Time. Out. Somebody hydrate me.","mp3":"","model":"eleven_v4"}],"tombo":[{"text":"I called it! Get your own monster!","mp3":"","model":"eleven_v4"}],"dc1":[{"text":"Field day! Eggs on spoons! GO!","mp3":"","model":"eleven_v4"}],"dc2":[{"text":"Three more! Squeeze! Don't you DARE quit!","mp3":"","model":"eleven_v4"}],"tombo2":[{"text":"Hold the rope, Tom! I'm taking the outside lane!","mp3":"","model":"eleven_v4"}],"tombo3":[{"text":"Sixty floors, Tom! Don't you dare drop behind my pace!","mp3":"","model":"eleven_v4"}],"ff2":[{"text":"My girls. Okay, hands together! Nobody stops the three of us!","mp3":"","model":"eleven_v4"}]};
